B=[
dict(a=1,z=2,star=3,lit=L(1,2),
key=[('說完','H3615','kekhallot','完畢'),('亞撒利雅','H5838','azaryah','亞撒利雅'),('狂傲的人','H2086','hazzedim','狂傲的人'),('說謊言','H8267','sheker','謊言'),('差遣','H7971','shelakhkha','差遣'),('寄居','H1481','lagur','寄居')],
gram=['**{H2086}**（zed，狂傲）：「**一切狂傲的人**」。**這個字，常描寫自以為是、不肯低頭的人。****四十二章，他們說「我們都必聽從」；現在，這一群人，被稱為「狂傲」。**','**{H8267}**（sheker，謊言）：「**你說謊言**」。**這是耶利米書的核心字之一：二十三章，耶利米一直在指責「說謊的先知」；現在，輪到他，被人指為「說謊」。****這是一個整卷書的反轉。**'],
exp=['四十三章，是四十二章的結果。**一節說：耶利米向眾百姓，說完了耶和華他們神的一切話，就是耶和華他們神差遣他去所說的一切話。****這一句，很重：他說完了。****沒有留下一句，沒有隱瞞，沒有修改。****這是他在四十二章4節，答應他們的：無論回答什麼，我必都告訴你們，毫不隱瞞。**','二節，是這一章最令人心痛的反應：**何沙雅的兒子亞撒利雅和加利亞的兒子約哈難，並一切狂傲的人，就對耶利米說：你說謊言！耶和華我們的神並沒有差遣你來說：你們不可進入埃及，在那裡寄居。****請你留意這個詞：「狂傲的人」。****四十二章6節，他們起誓，無論好歹，都必聽從；現在，答案來了，他們說：你說謊言。**','這是整卷書，最大的反轉之一：**二十三章，耶利米一直在對抗說謊的先知；四十三章，他自己，被人說成說謊的先知。****這不是一件偶然的事。****當神的話，與人心裡已經選好的方向，不一樣的時候，人往往不是改變方向，而是懷疑說話的人。**','請你留意約哈難：**他是四十章，那位警告基大利的人；四十一章，那位追回被擄之人的人。****他一直是一個清醒、行動的人。****現在，在四十三章，他站在了反對耶利米的那一邊。****這是一個很沉重的提醒：昨天，曾經對的人，今天，也可能走錯。****經文沒有說他是壞人，經文只記：他說了這句話。**']),
dict(a=3,z=3,star=3,lit=L(3,3),
key=[('巴錄','H1263','barukh','巴錄'),('挑唆','H5496','massit','慫恿、挑唆'),('迦勒底人','H3778','kasdim','迦勒底人'),('被殺','H4191','lehamit','殺死'),('被擄','H1540','lehagalot','使被擄')],
gram=['**{H5496}**（suth，挑唆）：「**巴錄挑唆你害我們**」。**這個動詞，是「慫恿、煽動」。****三十八章22節，王的朋友「催逼」他，用的也是這個字。****現在，他們指控巴錄，用同一個字。**','**{H1263}**（barukh，巴錄）：「**尼利亞的兒子巴錄**」。**「巴錄」的名字，意思是「蒙福的」。****在這裡，他被人說成：害人的人。**'],
exp=['三節，他們給了一個解釋：**這是尼利亞的兒子巴錄，挑唆你害我們，要將我們交在迦勒底人的手中，使我們有被殺的，有被擄到巴比倫去的。****請你注意：他們沒有說耶利米是壞人。****他們說，是巴錄在背後，挑唆他。**','這個解釋，很熟悉：**當我們不想承認一個人說的話是真的，我們就找一個「背後的人」，把責任推過去。****他是被誰影響的？他是被誰利用的？****這是一種很常見的方式，讓我們不必面對那個話本身。**','我們也要為巴錄，多停一下。**三十六章，他是那位被神記得的文士；四十五章，他有一篇專門的話。****現在，在四十三章，他被指控了。****聖經沒有為他辯護，只是記下：這個忠心的書記，也被人說成是害人的人。****忠心的人，常常也是第一個被誤會的人。**']),
dict(a=4,z=5,star=3,lit=L(4,5),
key=[('不聽從','H8085','shama','聽從'),('住在','H3427','lashevet','居住'),('剩下的','H7611','sheerit','剩下的人'),('被趕到各國','H5080','niddekhu','被趕散'),('寄居','H1481','lagur','寄居')],
gram=['**{H8085}**（shama，聽從）：「**不聽從耶和華的話住在猶大地**」。**這個動詞，是整卷書的鑰匙。****四十二章4節，耶利米說，我已經聽見你們了；四十三章4節，經文說，他們不聽。**','**{H5080}**（nadach，趕散）：「**從被趕到各國回來**」。**這是四十章12節，同一個詞：他們是被趕散的，後來回來。****現在，這群回來的人，又要被帶走。**'],
exp=['四節，聖經用一句話，記下這個團體的決定：**於是加利亞的兒子約哈難和一切軍長，並眾百姓，不聽從耶和華的話，住在猶大地。****請你注意這個句子的結構：「不聽從耶和華的話」，後面接著「住在猶大地」。****意思是：神說，住在這地；他們，沒有聽從這個「住在這地」的話。**','這一節，常常被讀成：他們不聽從，去了埃及。**可是原文的重點是：他們不聽從「住在這地」的話。****也就是說，他們失去的，不只是一個地方，而是一個應許：「你們若仍住在這地，我就建立你們」（四十二章10節）。**','五節，是整個行動的細節：**約哈難和一切軍長，卻將所剩下的猶大人，就是從被趕到各國回來，在猶大地寄居的，**……請你留意：這一群人，是四十章12節，那些「從所趕到的各處回來」的人。****他們原來是被趕散的；他們曾經聽見，回來了；現在，他們又被帶走。**','我們要看見一個很安靜的悲劇：**這群人，剛剛才從各國回來，剛剛才積蓄了酒和夏天的果子，剛剛才開始重建。****現在，他們再一次，被帶離這片土地。****這一次，不是被敵人擄走，是被自己人帶走。**']),
dict(a=6,z=7,star=3,lit=L(6,7),
key=[('男人','H1397','gevarim','男人'),('婦女','H802','nashim','婦女'),('孩童','H2945','tof','孩子'),('眾公主','H1323','bnot hamelekh','公主'),('答比匿','H8471','takhpankhes','答比匿'),('埃及','H4714','mitsrayim','埃及'),('不聽從','H8085','shamu','聽從')],
gram=['**{H8471}**（takhpankhes，答比匿）：「**到了答比匿**」。**答比匿，是埃及東北邊境的一座要塞城。****這是他們進入埃及的第一站。**','**{H802}**（ishshah，婦女）：「**男人、婦女、孩童，和眾公主**」。**這是一個完整的名單：每一個人，都被帶走。****不是只有決定的人，是所有人。**'],
exp=['六節，是被帶走的名單：**男人、婦女、孩童，和眾公主，並護衛長尼布撒拉旦所留在沙番的孫子亞希甘的兒子基大利那裡的眾人，與先知耶利米，以及尼利亞的兒子巴錄，**都帶入埃及地。','請你留意最後兩個名字：**先知耶利米，以及尼利亞的兒子巴錄。****他們是被反對的人，是被指控的人。****可是，他們也被帶走了。****決定的人，帶著被反對的人，一起去了埃及。**','七節：**都帶入埃及地，到了答比匿。這是因他們不聽從耶和華的話。****聖經用一句話，作了結語：這是因他們不聽從耶和華的話。****沒有修飾，沒有安慰。****答比匿，是埃及東北邊境的要塞城，是他們進入埃及的第一站。**','我們要看見這一幕的重量：**神的僕人耶利米，一生說「住在這地」；現在，他被帶到他一生勸人不要去的地方。****我們不為這件事加上解釋，只看見：有時候，一個人忠心說了話，卻仍然被帶往他不想去的地方。****聖經記下這個事實，也記下，神仍然與他同在，因為下一節，神的話，又臨到他了。**']),
dict(a=8,z=9,star=3,lit=L(8,9),
key=[('大石頭','H68','avanim','石頭'),('藏','H2934','utemantem','藏'),('灰泥','H4423','bammelet','灰泥'),('砌磚','H4404','malben','磚地'),('法老','H6547','paroh','法老'),('宮門','H6607','petakh','門口')],
gram=['**{H2934}**（taman，藏）：「**藏在砌磚的灰泥中**」。**這是一個很具體的動作：把大石頭，埋在磚地的泥裡。****這是一個象徵性的行動，像耶利米書十三章的腰帶、十九章的瓶。**','**{H6547}**（paroh，法老）：「**答比匿法老的宮門那裡**」。**這個宮門，是法老在答比匿的官邸入口。****耶利米把一個預言，埋在法老宮門口的地面。**'],
exp=['八節：**在答比匿，耶和華的話臨到耶利米說。****請你留意：神的話，在埃及，仍然臨到耶利米。****他被帶離了猶大地，神的話，沒有離開他。**','九節，神吩咐他做一個象徵性的行動：**你在猶大人眼前，要用手拿幾塊大石頭，藏在砌磚的灰泥中，就是在答比匿法老的宮門那裡。****這與耶利米書的其他象徵性的行動，是一類：十三章的麻布腰帶，十九章的瓦瓶，二十七章的軛。****這一次，是幾塊大石頭，埋在磚地的泥裡。**','請你留意：**「在猶大人眼前」。****這個預言，不是對法老說的，是對那些被帶到埃及的猶大人說的。****他們逃到埃及，以為這是安全的地方；耶利米，在他們眼前，把石頭埋在法老宮門口。****這個動作的意思，要在下一節，才說出來。**']),
dict(a=10,z=11,star=3,lit=L(10,11),
key=[('我的僕人','H5650','avdi','僕人'),('寶座','H3678','kisso','寶座'),('寶帳','H8237','shafrir','華蓋、寶帳'),('死亡','H4194','mavet','死亡'),('擄掠','H7628','shevi','擄掠'),('刀殺','H2719','kherev','刀')],
gram=['**{H5650}**（eved，僕人）：「**我必召我的僕人巴比倫王尼布甲尼撒來**」。**這是耶利米書第三次，稱尼布甲尼撒為「我的僕人」（二十五9；二十七6；四十三10）。****這個稱呼，說的是他的角色：他是神手中的工具，不是神的朋友。**','**{H3678}**（kisse，寶座）：「**在所藏的石頭上我要安置他的寶座**」。**石頭，是被藏在地上的；他的寶座，要安置在這些石頭上。****預言的意思，在這裡說出來。**'],
exp=['十節，神說出這個象徵動作的意思：**萬軍之耶和華以色列的神如此說：我必召我的僕人巴比倫王尼布甲尼撒來。在所藏的石頭上，我要安置他的寶座；他必將光華的寶帳，支搭在其上。****請你注意：「我的僕人」。****這是耶利米書第三次，稱尼布甲尼撒為神的僕人。****這個稱呼，說的是他的角色：在神的手中，他是一個工具。**','這個預言，說得很具體：**你們逃到答比匿，躲在法老宮門口；我要在這些石頭上，安置尼布甲尼撒的寶座。****你們所以為安全的地方，就是他要坐下的地方。****十一節：他要來攻擊埃及地，定為死亡的，必致死亡；定為擄掠的，必被擄掠；定為刀殺的，必交刀殺。**','我們要誠實：這一段，是一個預言，不是一個時間表。**經文沒有告訴我們，什麼時候應驗，我們也不推算日子；我們只讀神對這一群人說的話：你們所逃往的地方，不是避難所。****我們也不把這個預言，套用到今日任何一個政權；這是對那個時刻、那個地方的話。**','請你留意這三個「定為」：**定為死亡的，必致死亡；定為擄掠的，必被擄掠；定為刀殺的，必交刀殺。****這是一個很嚴肅的句子，也是一個很誠實的句子：審判，不是隨機的，是神定的。****可是，在這之前，神已經給了他們一條路：留在這地。****他們沒有選。**']),
dict(a=12,z=13,star=2,lit=L(12,13),
key=[('使火著起','H3341','vehitsatti','點火'),('廟宇','H1004','battei','房屋、廟'),('披上外衣','H5844','atah','披上'),('牧人','H7462','roeh','牧人'),('柱像','H4676','matstsevot','石柱'),('伯‧示麥','H1053','beth shemesh','伯示麥'),('打碎','H7665','shavar','打碎')],
gram=['**{H5844}**（atah，披上）：「**好像牧人披上外衣**」。**這個畫面，很安靜：一個牧人，把外衣披在身上，輕輕鬆鬆，就走了。****神說：他得埃及，就像這樣容易。**','**{H1053}**（beth shemesh，伯‧示麥）：「**伯‧示麥的柱像**」。**「伯‧示麥」，意思是「太陽的家」，通常被認為是埃及的太陽城。****那裡，有許多石柱，用來敬拜太陽神。**'],
exp=['十二節：**我要在埃及神的廟中，使火著起，巴比倫王要將廟宇焚燒，神像擄去；他要得埃及地，好像牧人披上外衣，從那裡安然而去。****請你看這個畫面：他得埃及地，像牧人披上外衣。****輕鬆，安靜，不費力。**','這是一個令人驚訝的比喻：**一個很強大的國家，在神的話裡，只是一件外衣；一個很強大的王，只是一位披上外衣的牧人。****埃及是猶大人以為最安全的地方，神說：在我眼中，它是一件外衣。****這是福音的另一面：真正的安全，不在最強大的地方，而在神的話裡。**','十三節：**他必打碎埃及地伯‧示麥的柱像，用火焚燒埃及神的廟宇。****伯‧示麥，意思是「太陽的家」，通常被認為是埃及的太陽城，那裡有許多敬拜太陽神的石柱。****神的預言，不只是說，埃及的軍隊要敗；也說，埃及所倚靠的神明，也要被打碎。**','這一章，就在這裡結束，沒有安慰，只有一個很清楚的畫面：**一群人，以為在埃及找到了避難所；神的僕人，在他們眼前，把石頭埋在地上，說：這裡，要成為另一位王的寶座。****我們不知道他們當時怎麼想，聖經沒有說。****我們可以安靜地，問自己：我現在的避難所，是什麼？**']),
]
